(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('high');
    g.dpr = 1;
    g.renderer.setPixelRatio(1);
    g.resize();
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    Object.assign(g.env.weather, { cloud: 0.15, cloudTarget: 0.15, rain: 0, rainTarget: 0, timer: 1e9 });
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    g.hud.show(false);
    __rhf.god(true);
    g.wildlife.threatPos = () => ({ x: 1e7, z: 1e7, loud: 0 });
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    // game seconds, however slow the frames
    window.__gameWait = async (s) => {
      const t0 = g.time;
      await __until(() => g.time - t0 > s, 400000);
    };
    window.__look = (x, z, tx, ty, tz) => {
      const P = g.player;
      P.place(x, z, 0);
      P.tool = 'none';
      g.viewmodel.setTool('none');
      const dx = tx - x;
      const dz = tz - z;
      P.yaw = Math.atan2(-dx, -dz);
      P.pitch = Math.atan2(ty - (P.pos.y + 1.7), Math.hypot(dx, dz));
    };
    return 'ok';
  })()

(async () => {
    const g = __rhf.game;
    g.env.setTime(21.2);
    await __gameWait(0.5);
    const hp = g.world.lakeById.hotpool;
    const s = g.env.sunDir;
    const l = Math.hypot(s.x, s.z) || 1;
    const x = hp.x - (s.x / l) * 26;
    const z = hp.z - (s.z / l) * 26;
    __look(x, z, hp.x, hp.level + 2.5, hp.z);
    await __gameWait(6);
    return 'steam at dusk, sun elevation ' + g.env.sunElevation.toFixed(1) + ', exposure ' + g.renderer.toneMappingExposure.toFixed(3);
  })()

(async () => {
    const g = __rhf.game;
    g.env.setTime(1.0);
    await __gameWait(6);
    return 'steam at night, night ' + g.env.night.toFixed(2) + ', exposure ' + g.renderer.toneMappingExposure.toFixed(3);
  })()

(async () => {
    const g = __rhf.game;
    g.env.setTime(21.2);
    await __gameWait(0.5);
    const G = g.props.geyser;
    const s = g.env.sunDir;
    const l = Math.hypot(s.x, s.z) || 1;
    __look(G.x - (s.x / l) * 40, G.z - (s.z / l) * 40, G.x, G.y + 9, G.z);
    g.areas.cycle = 'rumble';
    g.areas.t = 0.1;
    await __until(() => g.areas.cycle === 'blow' && g.areas.t > 2.5, 300000);
    return 'geyser ' + g.areas.cycle + ' ' + g.areas.t.toFixed(1);
  })()

(async () => {
    const g = __rhf.game;
    const W = g.world;
    g.env.setTime(20.4);
    const p = W.river.sample(W.fallsS + 30);
    const t = W.river.sample(W.fallsS);
    const w = W.riverWidth(W.fallsS + 30) + 5;
    __look(p.x - p.tz * w, p.z + p.tx * w, t.x, W.riverLevel(W.fallsS) - 6, t.z);
    g.bears.bears.forEach((b) => {
      if (b.mode !== 'fish') {
        b.state = 'gone';
        b.t = 9999;
      }
    });
    await __gameWait(6);
    return 'falls in the evening, exposure ' + g.renderer.toneMappingExposure.toFixed(3);
  })()

(async () => {
    const g = __rhf.game;
    const W = g.world;
    g.env.setTime(13);
    const b = W.place('bend');
    // the trees (and their colliders) are planted round the camera: go there first
    __look(b.x, b.z, b.x + 10, W.heightAt(b.x, b.z) + 2, b.z);
    await __gameWait(3);
    let spot = null;
    let best = 0;
    for (let k = 0; k < 3000; k++) {
      const x = b.x + Math.sin(k * 2.399) * (20 + k * 0.05);
      const z = b.z + Math.cos(k * 2.399) * (20 + k * 0.05);
      if (!W.inBounds(x, z, 80) || W.waterAt(x, z) || W.slopeAt(x, z) > 0.25) continue;
      let n = 0;
      for (const c of g.colliders.circlesNear(x, z, 9)) if (c.tag === 'tree' && (c.x - x) ** 2 + (c.z - z) ** 2 < 81) n++;
      if (n > best) {
        best = n;
        spot = { x, z };
      }
      if (n >= 12) break;
    }
    __look(spot.x, spot.z, spot.x + 30, W.heightAt(spot.x, spot.z) + 3, spot.z + 10);
    await __gameWait(5);
    return 'forest at noon: ' + best + ' trees within 9 m, exposure ' + g.renderer.toneMappingExposure.toFixed(3);
  })()

